/** Plain ImageRef (what content stores), without the extras. */
export const siteImage = (slot: SitePhotoSlot): ImageRef => {
  const { key, width, height, widths } = SITE_PHOTOS[slot];
  return { key, width, height, widths: [...widths] };
};

/** Default photos are files of the web app itself, not uploads. */
export const isSitePhoto = (image: ImageRef): boolean => image.key.startsWith("images/");

const byKey = new Map<string, SitePhoto>(Object.values(SITE_PHOTOS).map((entry) => [entry.key, entry]));
export const sitePhotoByKey = (key: string): SitePhoto | undefined => byKey.get(key);
